import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";var i=JSON.parse(`{"title":"Every declaration carries a complete TSDoc contract","description":"","frontmatter":{},"headers":[],"relativePath":"reference/rules/tsdoc-coverage.md","filePath":"reference/rules/tsdoc-coverage.md"}`),a={name:`reference/rules/tsdoc-coverage.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="every-declaration-carries-a-complete-tsdoc-contract" tabindex="-1">Every declaration carries a complete TSDoc contract <a class="header-anchor" href="#every-declaration-carries-a-complete-tsdoc-contract" aria-label="Permalink to “Every declaration carries a complete TSDoc contract”">​</a></h1><p>Every function-like and every type member needs a TSDoc block, with <code>@param</code> per parameter and <code>@returns</code> when something is returned.</p><h2 id="why-it-is-a-rule" tabindex="-1">Why it is a rule <a class="header-anchor" href="#why-it-is-a-rule" aria-label="Permalink to “Why it is a rule”">​</a></h2><p>Undocumented code forces the next reader to infer the contract from the implementation, which is how a refactor silently changes behavior. This applies to tools as much as to people: anything editing the code later works from what the declaration says about itself.</p><h2 id="what-is-expected" tabindex="-1">What is expected <a class="header-anchor" href="#what-is-expected" aria-label="Permalink to “What is expected”">​</a></h2><ul><li>A <code>/** */</code> block above the declaration, exported or not.</li><li><code>@param</code> for each parameter, <code>@returns</code> when a value is returned.</li><li><code>//</code> is for code; a <code>//</code> line above a declaration is documentation in the wrong form.</li><li>Runs of <code>//</code> comments stay short. Longer explanation belongs in the enclosing TSDoc block.</li></ul><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to “Options”">​</a></h2><p>The default requires documentation on everything, module-local or not. A codebase adopting the rule late can start lower and tighten over time:</p><ul><li><code>requireOn: &quot;exported&quot;</code> checks only the surface other files consume.</li><li><code>requireParams: false</code> and <code>requireReturns: false</code> waive the tag checks and keep only the requirement that a TSDoc block exists.</li><li><code>maxInlineCommentLines</code> moves the cap on <code>//</code> runs (default 2).</li></ul><h2 id="what-is-not-checked" tabindex="-1">What is not checked <a class="header-anchor" href="#what-is-not-checked" aria-label="Permalink to “What is not checked”">​</a></h2><p>Whether the prose is any good. That remains a human question.</p>`,11)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};